$cw=[int]($inputArt.Width/3);$ch=[int]($inputArt.Height/2);$control=$inputArt.Clone([System.Drawing.Rectangle]::new(0,0,$cw,$ch),[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);$top=[CombatPose50]::HoodTop($control,[double[]]$plan.controlHoodRegion);$sole=[CombatPose50]::Sole($control);$scale=$plan.bodyControlHeight/($sole[2]-$top);if($scale -lt 0.2 -or $scale -gt 1.2){throw 'Invalid shared source scale'}
