$g=[System.Drawing.Graphics]::FromImage($atlas);$g.CompositingMode=[System.Drawing.Drawing2D.CompositingMode]::SourceCopy;$g.DrawImageUnscaled($pose,$x,$y);$g.Dispose();$pose.Save((Join-Path $dir ('pose-'+$i+'.png')))
$components=[CombatPose50]::Components($pose);$significant=@($components|Where-Object {$_ -gt 3});$renderFoot=[CombatPose50]::Sole($pose);$quality+=@{frame=$i;sourceSole=$foot;sourceTranslation=@($tx,$ty);renderedSole=$renderFoot;alphaCorner=$pose.GetPixel(0,0).A;componentsOver3Pixels=$significant;detachedComponentsOver3Pixels=[Math]::Max(0,$significant.Count-1)};$frames+=@{x=$x;y=$y;width=384;height=320;pivot=@{x=192;y=289};sourceIdleFrame=$i;previousFrame=$plan.previousLoop[$i];label=('Chien dau - nhip '+($i+1));sourceTranslation=@($tx,$ty)};$cell.Dispose()
}
